def orfs(s,label):
    res=[]
    for frame in range(3):
        i=frame
        # find stop-free regions and ATGs
        # simplest: scan for ATG then extend to stop
        pos=frame
        while pos < len(s)-2:
            if s[pos:pos+3]=='ATG':
                j=pos+3
                while j < len(s)-2 and s[j:j+3] not in stops:
                    j+=3
                if j < len(s)-2:
                    length=j-pos
                    if length>=300:  # >=100 aa
                        res.append((label,frame+1,pos+1,j+2,length,length//3))
            pos+=3
    return res

