import re
seq=open('region.fasta').read()
seq=''.join(l.strip() for l in seq.split('\n') if not l.startswith('>')).upper()
n=len(seq)
# homopolymers
for m in re.finditer(r'(A{4,}|T{4,}|G{4,}|C{4,})',seq):
    print('homopolymer',m.group(),m.start()+1,m.end())
# dinucleotide repeats >= 5 units
print('---dinuc---')
for unit in ['AT','TA','GC','CG','AG','CT','AC','GT','GA','TC','CA','TG']:
    for m in re.finditer('(?:%s){5,}'%unit,seq):
        print(unit, m.start()+1, m.end(), m.group())
# trinucleotide repeats >=4
print('---trinuc---')
seen=set()
for i in range(n-12):
    for L in range(12,40,3):
        u=seq[i:i+3]
        seg=seq[i:i+L]
        if len(seg)==L and seg==u*(L//3) and L>=15:
            if (i,L) not in seen:
                seen.add((i,L))
                print(u,i+1,i+L)

seq=open('region.fasta').read()
seq=''.join(l.strip() for l in seq.split('\n') if not l.startswith('>')).upper()
n=len(seq)
comp={'A':'T','T':'A','G':'C','C':'G'}
rc=''.join(comp[b] for b in reversed(seq))
stops={'TAA','TAG','TGA'}
print('n=',n)
for label,s in (('+',seq),('-',rc)):
    for f in range(3):
        # codon start positions (1-based in s coordinates): f+1, f+4, ...
        best=(0,None,None)
        run_start=None
        i=f
        while i+3<=len(s):
            cod=s[i:i+3]
            if cod in stops:
                if run_start is not None:
                    L=i-run_start
                    if L>best[0]: best=(L,run_start,i+3)
                    run_start=None
            else:
                if run_start is None: run_start=i
            i+=3
        if run_start is not None:
            L=len(s)-run_start
            if L>best[0]: best=(L,run_start,len(s))
        if best[0]>=250:
            a,b=best[1],best[2]
            if label=='+': coords=(a+1,b)
            else: coords=(n-b+1, n-a)
            print('strand',label,'frame',f+1,'stop-free bp',best[0],'s-coords',a+1,b,'genome coords',coords)
